<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class ClientDeliveryService
{
 use DeliveryOperations;
 public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly QuotationService $quotes) {}
 private function request(string $id,bool $client):array {$r=$this->row('extra_service_requests','request_id',$id);$s=$this->access->requireSite($r['site_id']);if((string)$s['client_id']!==(string)$r['client_id'])throw HttpException::notFound();if($client)$this->mapped($r['client_id']);return $r;}
 public function list(array $in,bool $client=false):array {$this->fields($in,['site_id']);$s=$this->access->requireSite($in['site_id']??null);if($client)$this->mapped($s['client_id']);$rows=$this->db->fetchAll('SELECT * FROM extra_service_requests WHERE company_id=:company AND site_id=:site AND client_id=:client ORDER BY request_id DESC LIMIT 200',['company'=>$this->company(),'site'=>$s['site_id'],'client'=>$s['client_id']]);foreach($rows as&$r){$r['quotation']=$r['quotation_id']?$this->quotes->detail((string)$r['quotation_id'],$client):null;$r['history']=$this->events('extra_service',$r['request_id']);}return $rows;}
 public function create(array $in,bool $client=false):array {return $this->atomic(function()use($in,$client){$this->fields($in,['site_id','request_type','title','details','starts_at','ends_at','required_guards']);$s=$this->access->requireSite($in['site_id']??null);if($client)$this->mapped($s['client_id']);$start=$this->at($in['starts_at']??null);$end=$this->at($in['ends_at']??null);if($start<=gmdate('Y-m-d H:i:s')||$end<=$start||strtotime($end.' UTC')-strtotime($start.' UTC')>7*86400||!in_array($in['request_type']??null,['EXTRA_GUARDS','EVENT'],true))throw HttpException::unprocessable('Choose future extra guard/event coverage lasting up to seven days.');$this->db->execute('INSERT INTO extra_service_requests(company_id,site_id,client_id,request_type,title,details,starts_at,ends_at,required_guards,created_by_user_id,created_at) VALUES(:company,:site,:client,:type,:title,:details,:start,:end,:guards,:actor,:now)',['company'=>$this->company(),'site'=>$s['site_id'],'client'=>$s['client_id'],'type'=>$in['request_type'],'title'=>$this->text($in['title']??null,150),'details'=>$this->text($in['details']??null,10000),'start'=>$start,'end'=>$end,'guards'=>$this->number($in['required_guards']??null,1,1000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('extra_service');});}
 public function quote(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['expected_revision','currency','unit_minor','tax_basis_points','terms','valid_until']);$r=$this->request($id,false);$this->revision($r,$in);if($r['state']!=='REQUESTED'||$r['starts_at']<=gmdate('Y-m-d H:i:s'))throw HttpException::conflict('Request is no longer available for quotation.');$s=$this->access->requireSite($r['site_id']);$q=$this->quotes->create(['client_id'=>$r['client_id'],'proposed_site_name'=>$s['site_name'],'title'=>$r['title'],'currency'=>$in['currency']??null,'lines'=>[['description'=>'One-off coverage '.$r['starts_at'].' to '.$r['ends_at'].' UTC; price per guard for the whole requested period','quantity'=>$r['required_guards'],'unit_minor'=>$in['unit_minor']??null]],'tax_basis_points'=>$in['tax_basis_points']??0,'terms'=>$in['terms']??null,'valid_until'=>$in['valid_until']??null]);$this->quotes->share($q['id'],['expected_revision'=>1]);$this->db->execute("UPDATE extra_service_requests SET quotation_id=:quote,state='QUOTED',revision=revision+1 WHERE company_id=:company AND request_id=:id",['quote'=>$q['id'],'company'=>$this->company(),'id'=>$id]);$this->history('extra_service',$id,'QUOTED','Quotation #'.$q['id']);return $q;});}
 private function coverage(array $r,array $ids):void {if(!$ids||count($ids)>200||count(array_unique($ids))!==count($ids))throw HttpException::unprocessable('Choose 1–200 distinct shift IDs.');$rows=[];$points=[$r['starts_at'],$r['ends_at']];foreach($ids as$id){$s=$this->row('shift_assignments','shift_assignment_id',$id);if((string)$s['site_id']!==(string)$r['site_id']||!empty($s['deleted_at'])||!in_array($s['assignment_status'],['ASSIGNED','CONFIRMED','IN_PROGRESS','COMPLETED'],true)||$s['shift_start_at']>=$r['ends_at']||$s['shift_end_at']<=$r['starts_at']||$this->row('employees','employee_id',$s['employee_id'])['employment_status']!=='ACTIVE')throw HttpException::conflict('A coverage shift is unavailable or belongs to another site.');$rows[]=$s;$points[]=max($r['starts_at'],$s['shift_start_at']);$points[]=min($r['ends_at'],$s['shift_end_at']);}sort($points);$points=array_values(array_unique($points));for($i=0;$i<count($points)-1;$i++){$guards=[];foreach($rows as$s)if($s['shift_start_at']<=$points[$i]&&$s['shift_end_at']>=$points[$i+1])$guards[$s['employee_id']]=true;if(count($guards)<(int)$r['required_guards'])throw HttpException::conflict('Assigned shifts do not cover the entire requested period.');}}
 public function action(string $id,string $action,array $in,bool $client=false):array {return $this->atomic(function()use($id,$action,$in,$client){$this->fields($in,['expected_revision','expected_hash','notes','shift_ids']);$r=$this->request($id,$client);$this->revision($r,$in);$notes=$this->text($in['notes']??null,1000);$state=$r['state'];$shifts=$r['shift_ids_json'];$completed=$r['completed_at'];$confirmed=$r['confirmed_at'];if($client&&in_array($action,['accept','decline'],true)&&$state==='QUOTED'){if($r['starts_at']<=gmdate('Y-m-d H:i:s'))throw HttpException::conflict('Requested coverage start passed.');return $this->quotes->decide((string)$r['quotation_id'],$action,['expected_hash'=>$in['expected_hash']??null,'notes'=>$notes]);}elseif(!$client&&$action==='schedule'&&$state==='ACCEPTED'){if(!is_array($in['shift_ids']??null)||!array_is_list($in['shift_ids']))throw HttpException::unprocessable('Provide shift IDs.');$q=$this->quotes->detail((string)$r['quotation_id']);if($q['state']!=='ACCEPTED')throw HttpException::conflict('Quotation acceptance changed.');$this->coverage($r,$in['shift_ids']);$shifts=json_encode($in['shift_ids'],JSON_THROW_ON_ERROR);$state='SCHEDULED';}elseif(!$client&&$action==='complete'&&$state==='SCHEDULED'){if($r['ends_at']>gmdate('Y-m-d H:i:s'))throw HttpException::conflict('Coverage period has not ended.');$this->coverage($r,json_decode($shifts,true));$state='COMPLETED';$completed=gmdate('Y-m-d H:i:s');}elseif($client&&$action==='confirm'&&$state==='COMPLETED'){$state='CONFIRMED';$confirmed=gmdate('Y-m-d H:i:s');}elseif($action==='cancel'&&in_array($state,['REQUESTED','QUOTED','ACCEPTED'],true)){$state='CANCELLED';if($r['quotation_id'])$this->db->execute("UPDATE service_quotations SET state='CANCELLED',revision=revision+1 WHERE company_id=:company AND quotation_id=:id AND state='SHARED'",['company'=>$this->company(),'id'=>$r['quotation_id']]);}else throw HttpException::conflict('Service request action unavailable.');$this->db->execute('UPDATE extra_service_requests SET state=:state,shift_ids_json=:shifts,completion_notes=:notes,completed_at=:completed,confirmed_at=:confirmed,revision=revision+1 WHERE company_id=:company AND request_id=:id',['state'=>$state,'shifts'=>$shifts,'notes'=>$notes,'completed'=>$completed,'confirmed'=>$confirmed,'company'=>$this->company(),'id'=>$id]);$this->history('extra_service',$id,strtoupper($action),$notes);return ['state'=>$state,'note'=>'Staff completion is an attestation; client confirmation is recorded separately. No invoice or automatic deployment is created.'];});}
 private function packet(string $id,bool $client=false):array {$r=$this->row('client_mobilisation_reviews','review_id',$id);$s=$this->access->requireSite($r['site_id']);if((string)$s['client_id']!==(string)$r['client_id'])throw HttpException::notFound();if($client)$this->mapped($r['client_id']);return $r;}
 public static function readinessHash(array $c,array $s,array $tasks,string $contacts,string $survey):string {return hash('sha256',json_encode([$c,$s,$tasks,$contacts,$survey],JSON_THROW_ON_ERROR));}
 public function packetHash(array $o,string $contacts,string $survey):string {$c=$this->row('contracts','contract_id',$o['contract_id']);$s=$this->row('sites','site_id',$o['site_id']);$tasks=$this->db->fetchAll('SELECT task_id,task_name,revision,completed_at,evidence_reference FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id ORDER BY task_id',['company'=>$this->company(),'id'=>$o['onboarding_id']]);return self::readinessHash($c,$s,$tasks,$contacts,$survey);}
 public function onboardings(array $in,bool $client=false):array {$this->fields($in,['site_id']);$s=$this->access->requireSite($in['site_id']??null);if($client)$this->mapped($s['client_id']);$rows=$this->db->fetchAll('SELECT * FROM site_onboardings WHERE company_id=:company AND site_id=:site ORDER BY onboarding_id DESC LIMIT 100',['company'=>$this->company(),'site'=>$s['site_id']]);foreach($rows as&$r){$r['tasks']=$this->db->fetchAll('SELECT * FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id ORDER BY task_id',['company'=>$this->company(),'id'=>$r['onboarding_id']]);$r['review']=$this->db->fetch('SELECT * FROM client_mobilisation_reviews WHERE company_id=:company AND onboarding_id=:id AND client_id=:client',['company'=>$this->company(),'id'=>$r['onboarding_id'],'client'=>$s['client_id']]);}return $rows;}
 public function prepare(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['expected_revision','contacts','survey_reference']);$o=$this->row('site_onboardings','onboarding_id',$id);$s=$this->access->requireSite($o['site_id']);if($o['state']!=='PREPARING')throw HttpException::conflict('Mobilisation is not preparing.');$contacts=$in['contacts']??null;if(!is_array($contacts)||!array_is_list($contacts)||count($contacts)<1||count($contacts)>20)throw HttpException::unprocessable('Provide 1–20 emergency contacts.');$normal=[];foreach($contacts as$c){if(!is_array($c))throw HttpException::unprocessable('Invalid contact.');$this->fields($c,['name','role','phone']);$normal[]=['name'=>$this->text($c['name']??null,150),'role'=>$this->text($c['role']??null,150),'phone'=>$this->text($c['phone']??null,80)];}$json=json_encode($normal,JSON_THROW_ON_ERROR);$survey=$this->text($in['survey_reference']??null,1000);$old=$this->db->fetch('SELECT review_id,revision FROM client_mobilisation_reviews WHERE company_id=:company AND onboarding_id=:id',['company'=>$this->company(),'id'=>$id]);if($this->number($in['expected_revision']??null,0)!==(int)($old['revision']??0))throw HttpException::conflict('Client packet changed.');$hash=$this->packetHash($o,$json,$survey);if($old){$this->db->execute("UPDATE client_mobilisation_reviews SET client_id=:client,contacts_json=:contacts,survey_reference=:survey,packet_hash=:hash,state='READY',revision=revision+1,prepared_by_user_id=:actor,prepared_at=:now,decision_by_user_id=NULL,decision_at=NULL,decision_notes=NULL WHERE company_id=:company AND review_id=:id",['client'=>$s['client_id'],'contacts'=>$json,'survey'=>$survey,'hash'=>$hash,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$old['review_id']]);$review=(string)$old['review_id'];}else{$this->db->execute('INSERT INTO client_mobilisation_reviews(company_id,onboarding_id,site_id,client_id,contacts_json,survey_reference,packet_hash,prepared_by_user_id,prepared_at) VALUES(:company,:onboarding,:site,:client,:contacts,:survey,:hash,:actor,:now)',['company'=>$this->company(),'onboarding'=>$id,'site'=>$s['site_id'],'client'=>$s['client_id'],'contacts'=>$json,'survey'=>$survey,'hash'=>$hash,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$review=(string)$this->db->connection()->lastInsertId();}$this->history('mobilisation',$id,'PREPARED','Client readiness review #'.$review);return ['id'=>$review];});}
 public function decidePacket(string $id,string $action,array $in):array {return $this->atomic(function()use($id,$action,$in){$this->fields($in,['expected_hash','notes']);$r=$this->packet($id,true);$o=$this->row('site_onboardings','onboarding_id',$r['onboarding_id']);$tasks=$this->db->fetchAll('SELECT completed_at FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id',['company'=>$this->company(),'id'=>$r['onboarding_id']]);if($r['state']!=='READY'||$o['state']!=='PREPARING'||count($tasks)!==7||array_filter($tasks,fn($t)=>!$t['completed_at'])||!is_string($in['expected_hash']??null)||!hash_equals($r['packet_hash'],$in['expected_hash'])||!hash_equals($r['packet_hash'],$this->packetHash($o,$r['contacts_json'],$r['survey_reference'])))throw HttpException::conflict('Complete all seven mobilisation tasks and prepare a current packet before client approval.');$state=match($action){'accept'=>'ACCEPTED','decline'=>'DECLINED',default=>throw HttpException::notFound()};$this->db->execute('UPDATE client_mobilisation_reviews SET state=:state,revision=revision+1,decision_by_user_id=:actor,decision_at=:now,decision_notes=:notes WHERE company_id=:company AND review_id=:id',['state'=>$state,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'notes'=>$this->text($in['notes']??null,2000),'company'=>$this->company(),'id'=>$id]);$this->history('mobilisation',$r['onboarding_id'],$state,'Client decision recorded.');return ['state'=>$state];});}
 public function activate(string $id):array {return $this->atomic(function()use($id){$o=$this->row('site_onboardings','onboarding_id',$id);$this->access->requireSite($o['site_id']);$r=$this->db->fetch('SELECT review_id FROM client_mobilisation_reviews WHERE company_id=:company AND onboarding_id=:id',['company'=>$this->company(),'id'=>$id])??throw HttpException::conflict('Prepare and obtain client approval first.');$this->packet((string)$r['review_id']);return $this->quotes->activate($id);});}
}
